cd /work; python3 - <<'EOF'
p='index.html'; s=open(p).read()
a=s.index('  // ---------- linear view ----------'); b=s.index('}).catch(err')
new='''  // ---------- linear view (whole series, brushable) ----------
  const lsvg = d3.select("#linear");
  const LW = +lsvg.attr("width");
  const m = { l: 62, r: 14, t: 50 };
  const mainH = 520;
  lsvg.append("text").attr("class", "axis-title").attr("x", 10).attr("y", 16).style("font-weight", "600")
    .text("Linear view: whole series, 2012–2026");
  lsvg.append("text").attr("class", "hint").attr("x", 10).attr("y", 34)
    .text("Drag horizontally to select a time range (highlighted in both views); click outside it to reset.");
  const x = d3.scaleUtc().domain([d3.utcYear.floor(data[0].date), d3.utcYear.ceil(data[data.length - 1].date)])
    .range([m.l, LW - m.r]);
  const y = d3.scaleLinear().domain(rScale.domain()).range([m.t + mainH, m.t]);

  lsvg.append("g").attr("transform", `translate(0,${m.t + mainH})`)
    .call(d3.axisBottom(x).ticks(d3.utcYear.every(1)).tickFormat(d3.utcFormat("%Y")));
  lsvg.append("g").attr("transform", `translate(${m.l},0)`)
    .call(d3.axisLeft(y).ticks(7).tickFormat(d3.format(",")))
    .call(a => a.selectAll(".tick line").clone().attr("x2", LW - m.l - m.r).attr("stroke", "#eee"));
  lsvg.append("text").attr("class", "axis-title").attr("transform", `translate(14,${m.t + mainH / 2}) rotate(-90)`)
    .attr("text-anchor", "middle").text("ARE consultations per 100,000 per week");
  lsvg.append("text").attr("class", "axis-title").attr("x", (m.l + LW - m.r) / 2).attr("y", m.t + mainH + 34)
    .attr("text-anchor", "middle").text("Date (Monday of ISO reporting week; tick = 1 January)");

  const segLine = d3.line().x(d => x(d.date)).y(d => y(d.value));
  const segData = years.map(yr => {
    const rows = byYear.get(yr).slice();
    const next = byYear.get(yr + 1);
    if (next) rows.push(next[0]);
    return { yr, rows };
  });
  const plot = lsvg.append("g");
  const segs = plot.selectAll("path.seg").data(segData).join("path").attr("class", "seg")
    .attr("fill", "none").attr("stroke", d => color(d.yr)).attr("stroke-width", 1.3).attr("d", d => segLine(d.rows));
  const segsHl = plot.selectAll("path.seghl").data(segData).join("path").attr("class", "seghl")
    .attr("fill", "none").attr("stroke", d => color(d.yr)).attr("stroke-width", 2);
  const brush = d3.brushX().extent([[m.l, m.t], [LW - m.r, m.t + mainH]]).on("brush end", brushed);
  const brushG = lsvg.append("g").call(brush);
  brushG.select(".selection").attr("fill", "#999").attr("fill-opacity", 0.12);
  const pkG = lsvg.append("g");
  const lpeaks = pkG.selectAll("path").data(peaks).join("path")
    .attr("d", d3.symbol(d3.symbolTriangle, 55)())
    .attr("transform", p => `translate(${x(p.date)},${y(p.value) - 2})`)
    .attr("fill", p => color(p.year)).attr("stroke", "#000")
    .on("mousemove", (ev, p) => showTip(ev, `<b>Peak of season ${p.season}</b><br>${p.kw}<br>${d3.format(",")(p.value)} per 100,000`))
    .on("mouseleave", hideTip);
  pkG.selectAll("text").data(peaks).join("text")
    .attr("text-anchor", "middle").style("font-size", "9px")
    .attr("x", p => x(p.date)).attr("y", p => y(p.value) - 9)
    .text(p => "W" + p.week);
  const selText = lsvg.append("text").attr("class", "hint").attr("x", m.l).attr("y", m.t + mainH + 60)
    .style("font-size", "13px").style("fill", "#222");

  const fmt = d3.utcFormat("%d %b %Y");
  function brushed(ev) {
    applySel(ev.selection ? ev.selection.map(x.invert) : null);
  }
  function applySel(range) {
    const inR = d => !range || (d.date >= range[0] && d.date <= range[1]);
    segs.attr("stroke-opacity", range ? 0.2 : 1);
    segsHl.attr("d", d => { if (!range) return null; const r = d.rows.filter(inR); return r.length ? segLine(r) : null; });
    lpeaks.attr("opacity", p => inR(p) ? 1 : 0.25);
    baseLines.attr("stroke-opacity", range ? 0.12 : 0.9);
    hlLines.attr("d", yr => {
      if (!range) return null;
      const rows = byYear.get(yr).filter(inR);
      return rows.length ? lineR(rows) : null;
    });
    peakMarks.attr("opacity", p => inR(p) ? 1 : 0.15);
    selText.text(range
      ? `Selected: ${fmt(range[0])} – ${fmt(range[1])} (${data.filter(inR).length} weeks, ${peaks.filter(inR).length} season peaks)`
      : "No selection: all weeks shown.");
  }

  // initial selection: the seasons that peaked in December (if any), else the last two seasons
  const focus = dec.length ? dec : done.slice(-2);
  const s0 = d3.min(bySeason.get(focus[0].season), d => d.date);
  const s1 = d3.max(bySeason.get(focus[focus.length - 1].season), d => d.date);
  brushG.call(brush.move, [x(s0), x(s1)]);
'''
s=s[:a]+new+s[b:]
s=s.replace('const leg = rsvg.append("g").attr("transform", `translate(${W - 62},40)`);','const leg = rsvg.append("g").attr("transform", `translate(${W - 70},50)`);')
open(p,'w').write(s)
EOF
render index.html

